const fs = require('fs')
const appFile = './src/App.jsx'
const backup = './src/App.jsx.step20-9-header-runtime-backup'
const templateFile = './public/mcross-estimate-template.xlsx'
const marker = '/* M-CROSS_STEP20_9_HEADER_RUNTIME */'

if (!fs.existsSync(appFile)) { console.error('src/App.jsxが見つかりません。'); process.exit(1) }
let s = fs.readFileSync(appFile, 'utf8')
if (s.includes(marker)) { console.log('STEP20.9は適用済みです'); process.exit(0) }
if (!s.includes('async function exportWorkOrderEstimate(workOrder)')) { console.error('見積書出力関数が見つかりません。'); process.exit(1) }

fs.mkdirSync('./public', { recursive: true })
fs.writeFileSync(templateFile, Buffer.from('', 'base64'))

const start = s.indexOf('  async function exportWorkOrderEstimate(workOrder) {')
const end = s.indexOf('\n  function updateWorkOrder(', start)
if (start === -1 || end === -1) { console.error('見積書出力関数の範囲が見つかりません。'); process.exit(1) }

const fn = `  ${marker}
  async function exportWorkOrderEstimate(workOrder) {
    if (!workOrder) return
    const items = Array.isArray(workOrder.estimateItems) ? workOrder.estimateItems : []
    if (!items.length) { window.alert('見積明細がありません。'); return }
    if (items.length > 32) { window.alert('見積明細は32行まで出力できます。'); return }

    try {
      const { default: ExcelJS } = await import('exceljs')
      const templateResponse = await fetch(new URL('/mcross-estimate-template.xlsx', window.location.origin), { cache: 'no-store' })
      if (!templateResponse.ok) throw new Error('見積書テンプレートを読み込めません HTTP ' + templateResponse.status)
      const workbook = new ExcelJS.Workbook()
      await workbook.xlsx.load(await templateResponse.arrayBuffer())
      const ws = workbook.getWorksheet('見積書')
      if (!ws) throw new Error('「見積書」シートが見つかりません')

      // 画像を含まないテンプレートを読み込んだ後、完成済み会社ヘッダーをExcelJSで追加します。
      // これにより既存画像のanchors読込エラーを回避します。
      const companyHeaderImage = workbook.addImage({
        base64: 'data:image/png;base64,',
        extension: 'png',
      })
      ws.addImage(companyHeaderImage, {
        tl: { col: 5.0, row: 3.3 },
        ext: { width: 405, height: 158 },
        editAs: 'oneCell',
      })

      ws.getCell('B5').value = workOrder.company ? workOrder.company + '　御中' : ''
      ws.getCell('J3').value = new Date()
      ws.getCell('J3').numFmt = 'yyyy年m月d日'
      ws.getCell('D13').value = workOrder.propertyName || ''
      ws.getCell('F13').value = workOrder.unit || ''
      ws.getCell('G13').value = workOrder.unit ? '号室' : ''
      ws.getCell('D14').value = workOrder.address || ''

      for (let rowNumber = 23; rowNumber <= 54; rowNumber += 1) {
        ws.getCell('C' + rowNumber).value = ''
        ws.getCell('F' + rowNumber).value = ''
        ws.getCell('H' + rowNumber).value = ''
        ws.getCell('I' + rowNumber).value = ''
        ws.getCell('J' + rowNumber).value = ''
        ws.getCell('K' + rowNumber).value = ''
      }
      items.forEach((item, index) => {
        const rowNumber = 23 + index
        ws.getCell('C' + rowNumber).value = item.name || ''
        ws.getCell('F' + rowNumber).value = item.specification || ''
        ws.getCell('H' + rowNumber).value = Number(item.quantity || 0)
        ws.getCell('I' + rowNumber).value = item.unit || ''
        ws.getCell('J' + rowNumber).value = Number(item.unitPrice || 0)
        ws.getCell('K' + rowNumber).value = Number(item.amount || 0)
      })

      const subtotal = items.reduce((sum, item) => sum + (Number(item.amount) || 0), 0)
      const tax = Math.floor(subtotal * 0.1)
      const total = subtotal + tax
      ws.getCell('K55').value = subtotal
      ws.getCell('K56').value = tax
      ws.getCell('K57').value = total
      ws.getCell('E19').value = total
      ws.pageSetup.printArea = 'B3:K57'
      ws.pageSetup.fitToPage = true
      ws.pageSetup.fitToWidth = 1
      ws.pageSetup.fitToHeight = 1

      const buffer = await workbook.xlsx.writeBuffer()
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = ['見積書', workOrder.propertyName || '物件', workOrder.unit ? workOrder.unit + '号室' : ''].filter(Boolean).join('_') + '.xlsx'
      document.body.appendChild(link)
      link.click()
      link.remove()
      URL.revokeObjectURL(url)
      updateWorkOrder(workOrder.id, { estimateStatus: '提出済' })
    } catch (error) {
      console.error(error)
      window.alert('見積書を出力できませんでした：' + (error?.message || String(error)))
    }
  }
`

fs.copyFileSync(appFile, backup)
s = s.slice(0, start) + fn + s.slice(end)
fs.writeFileSync(appFile, s, 'utf8')
console.log('STEP20.9 固定ヘッダー実行時追加方式 OK')
console.log('アンカーエラーの原因だったテンプレート内画像を除去しました')
console.log('見積出力時にExcelJSで固定ヘッダー画像を新規追加します')
console.log('次に npm run build → npm run dev → 新しい見積書を出力してください')
console.log('バックアップ:', backup)
